package main

import "fmt"

func min(a, b int) int {
	if a < b {
		return a
	} else {
		return b
	}
}

func main() {
	var y, b, r int
	fmt.Scan(&y, &b, &r)
	ans_r := min(y + 2, min(b + 1, r))
	fmt.Println((ans_r - 1) * 3)
}
